			ObjectData raw = new ObjectData(asOverride);
			raw.damageXpValues().put(isDealt ? EventType.DEAL_DAMAGE : EventType.RECEIVE_DAMAGE, Map.of(damageType, award));
			registerConfiguration(asOverride, oType, objectID, raw);
