				if (mc.player.isCrouching()
						&& (!mc.player.getMainHandItem().isEmpty() || !mc.player.getOffhandItem().isEmpty())) {
					ItemStack salvageStack = mc.player.getMainHandItem().isEmpty() ? mc.player.getOffhandItem()
							: mc.player.getMainHandItem();
					gatherSalvageData(salvageStack)
							.forEach(line -> lines.addAll(ClientUtils.ctc(line, tooltipWidth)));
				} else
					lines.addAll(ClientUtils.ctc(LangProvider.SALVAGE_TUTORIAL_USAGE.asComponent(), tooltipWidth));
			} else
				return; // stop render if none of the viewing cases are met.

			// RENDER
			guiGraphics.pose().pushPose();
			RenderSystem.enableBlend();
			if (!lines.isEmpty()) {
				int i = 0;
				int j = lines.size() == 1 ? -2 : 0;

				for (ClientTooltipComponent clienttooltipcomponent : lines) {
					int k = clienttooltipcomponent.getWidth(mc.font);
					if (k > i) {
						i = k;
					}

					j += clienttooltipcomponent.getHeight();
				}

				int l = renderLeft;
				int i1 = renderTop;
				guiGraphics.pose().pushPose();
				Tesselator tesselator = Tesselator.getInstance();
				BufferBuilder bufferbuilder = tesselator.getBuilder();
				RenderSystem.setShader(GameRenderer::getPositionColorShader);
				bufferbuilder.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_COLOR);
				Matrix4f matrix4f = guiGraphics.pose().last().pose();
				TooltipRenderUtil.renderTooltipBackground(guiGraphics, l, i1, i, j, 400);
				RenderSystem.enableDepthTest();
				RenderSystem.enableBlend();
				RenderSystem.defaultBlendFunc();
				BufferUploader.drawWithShader(bufferbuilder.end());
				MultiBufferSource.BufferSource multibuffersource$buffersource = MultiBufferSource
						.immediate(Tesselator.getInstance().getBuilder());
				guiGraphics.pose().translate(0.0F, 0.0F, 400.0F);
				int k1 = i1;

				for (int l1 = 0; l1 < lines.size(); ++l1) {
					ClientTooltipComponent clienttooltipcomponent1 = lines.get(l1);
					clienttooltipcomponent1.renderText(mc.font, l, k1, matrix4f, multibuffersource$buffersource);
					k1 += clienttooltipcomponent1.getHeight() + (l1 == 0 ? 2 : 0);
				}

				multibuffersource$buffersource.endBatch();
				k1 = i1;

				for (int i2 = 0; i2 < lines.size(); ++i2) {
					ClientTooltipComponent clienttooltipcomponent2 = lines.get(i2);
					clienttooltipcomponent2.renderImage(mc.font, l, k1, guiGraphics);
					k1 += clienttooltipcomponent2.getHeight() + (i2 == 0 ? 2 : 0);
				}

			}
			guiGraphics.pose().popPose();
		}
	}

protected static void fillGradient(Matrix4f pMatrix, BufferBuilder pBuilder, int pX1, int pY1, int pX2, int pY2,
			int pBlitOffset, int pColorA, int pColorB) {
		float f = (float) (pColorA >> 24 & 255) / 255.0F;
		float f1 = (float) (pColorA >> 16 & 255) / 255.0F;
		float f2 = (float) (pColorA >> 8 & 255) / 255.0F;
		float f3 = (float) (pColorA & 255) / 255.0F;
		float f4 = (float) (pColorB >> 24 & 255) / 255.0F;
		float f5 = (float) (pColorB >> 16 & 255) / 255.0F;
		float f6 = (float) (pColorB >> 8 & 255) / 255.0F;
		float f7 = (float) (pColorB & 255) / 255.0F;
		pBuilder.vertex(pMatrix, (float) pX2, (float) pY1, (float) pBlitOffset).color(f1, f2, f3, f).endVertex();
		pBuilder.vertex(pMatrix, (float) pX1, (float) pY1, (float) pBlitOffset).color(f1, f2, f3, f).endVertex();
		pBuilder.vertex(pMatrix, (float) pX1, (float) pY2, (float) pBlitOffset).color(f5, f6, f7, f4).endVertex();
		pBuilder.vertex(pMatrix, (float) pX2, (float) pY2, (float) pBlitOffset).color(f5, f6, f7, f4).endVertex();
	}

private List<MutableComponent> gatherSalvageData(ItemStack stack) {
		List<MutableComponent> outList = new ArrayList<>();
		for (Map.Entry<ResourceLocation, SalvageData> entry : Core.get(LogicalSide.CLIENT).getLoader().ITEM_LOADER
				.getData(RegistryUtil.getId(stack)).salvage().entrySet()) {
			outList.add(MutableComponent.create(
					new ItemStack(ForgeRegistries.ITEMS.getValue(entry.getKey())).getDisplayName().getContents()));
			SalvageData data = entry.getValue();
			if (!data.levelReq().isEmpty()) {
				outList.add(LangProvider.SALVAGE_LEVEL_REQ.asComponent().withStyle(ChatFormatting.UNDERLINE));
				for (Map.Entry<String, Integer> req : data.levelReq().entrySet()) {
					outList.add(Component.translatable("pmmo." + req.getKey())
							.append(Component.literal(": " + req.getValue())));
				}
			}
			outList.add(LangProvider.SALVAGE_CHANCE.asComponent(data.baseChance(), data.maxChance())
					.withStyle(ChatFormatting.UNDERLINE));
			outList.add(LangProvider.SALVAGE_MAX.asComponent(data.salvageMax()).withStyle(ChatFormatting.UNDERLINE));
			if (!data.chancePerLevel().isEmpty()) {
				outList.add(LangProvider.SALVAGE_CHANCE_MOD.asComponent().withStyle(ChatFormatting.UNDERLINE));
				for (Map.Entry<String, Double> perLevel : data.chancePerLevel().entrySet()) {
					outList.add(Component.translatable("pmmo." + perLevel.getKey())
							.append(Component.literal(": " + perLevel.getValue())));
				}
			}
			if (!data.xpAward().isEmpty()) {
				outList.add(LangProvider.SALVAGE_XP_AWARD.asComponent().withStyle(ChatFormatting.UNDERLINE));
				for (Map.Entry<String, Long> award : data.xpAward().entrySet()) {
					outList.add(Component.translatable("pmmo." + award.getKey())
							.append(Component.literal(": " + award.getValue())));
				}
			}
		}
		return outList;
	}

public static void drawBoxHighlights(PoseStack stack, Set<BlockPos> vein)
    {
		Minecraft mc = Minecraft.getInstance();
        Vec3 cameraPos = mc.getEntityRenderDispatcher().camera.getPosition();
        stack.pushPose();
        stack.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());
        MultiBufferSource.BufferSource buffer = mc.renderBuffers().bufferSource();
        VertexConsumer builder = buffer.getBuffer(RenderType.lines());

        for(BlockPos pos : vein) {
            drawBoxHighlight(stack, builder, pos);
        }

        stack.popPose();
        RenderSystem.disableDepthTest();
        buffer.endBatch();
    }

public static void drawBoxHighlight(PoseStack stack, VertexConsumer builder, BlockPos pos)
    {
        stack.pushPose();
        Matrix4f matrix4f = stack.last().pose();
        int red = 255;
        int green = 0;
        int blue = 255;
        int alpha = 255;

        for(int i = 0; i < 12; i++)
        {
            int mode = i/4, j = i%4;
            float modulus = j%2, divide = j/2;
            switch(mode)
            {
                case 0:
                    builder.vertex(matrix4f, pos.getX() + modulus, pos.getY() + divide, pos.getZ()).color(red, green, blue, alpha).normal(0, 0, 0).endVertex();
                    builder.vertex(matrix4f, pos.getX() + modulus, pos.getY() + divide, pos.getZ() + 1).color(red, green, blue, alpha).normal(0, 0, 0).endVertex();
                    break;

                case 1:
                    builder.vertex(matrix4f, pos.getX(), pos.getY() + modulus, pos.getZ() + divide).color(red, green, blue, alpha).normal(0, 0, 0).endVertex();
                    builder.vertex(matrix4f, pos.getX() + 1, pos.getY() + modulus, pos.getZ() + divide).color(red, green, blue, alpha).normal(0, 0, 0).endVertex();
                    break;

                case 2:
                    builder.vertex(matrix4f, pos.getX() + divide, pos.getY(), pos.getZ() + modulus).color(red, green, blue, alpha).normal(0, 0, 0).endVertex();
                    builder.vertex(matrix4f, pos.getX() + divide, pos.getY() + 1, pos.getZ() + modulus).color(red, green, blue, alpha).normal(0, 0, 0).endVertex();
                    break;
            }
        }
        stack.popPose();
    }

@Override
	public void render(ForgeGui gui, GuiGraphics guiGraphics, float partialTick, int screenWidth, int screenHeight) {
		if (mc == null)
			mc = Minecraft.getInstance();
		if (fontRenderer == null)
			fontRenderer = mc.font;

		if(!mc.options.renderDebug){	
			guiGraphics.pose().pushPose();
			RenderSystem.enableBlend();

			if(Config.SKILL_LIST_DISPLAY.get())
				renderSkillList(guiGraphics, Config.SKILL_LIST_OFFSET_X.get(), Config.SKILL_LIST_OFFSET_Y.get());
			if(Config.VEIN_ENABLED.get() && Config.VEIN_GAUGE_DISPLAY.get())
				renderVeinGauge(guiGraphics, Config.VEIN_GAUGE_OFFSET_X.get(), Config.VEIN_GAUGE_OFFSET_Y.get());
			if(Config.GAIN_LIST_DISPLAY.get()) {
				if (ClientTickHandler.xpGains.size() >= 1 && ClientTickHandler.xpGains.get(0).duration <= 0)
					ClientTickHandler.xpGains.remove(0);
				renderGains(guiGraphics, Config.GAIN_LIST_OFFSET_X.get(), Config.GAIN_LIST_OFFSET_Y.get());
			}
			guiGraphics.pose().popPose();
		}
		if (ClientTickHandler.isRefreshTick()) {ClientTickHandler.resetTicks();}
	}

private void renderSkillList(GuiGraphics graphics, double skillListX, double skillListY) {
		final int renderX = (int)((double)mc.getWindow().getGuiScaledWidth() * skillListX);
		final int renderY = (int)((double)mc.getWindow().getGuiScaledHeight()* skillListY);
		if (ClientTickHandler.isRefreshTick()) {
			modifiers = core.getConsolidatedModifierMap(mc.player);	
			skillsKeys = core.getData().getXpMap(null).keySet().stream()
					.filter(a -> SkillsConfig.SKILLS.get().getOrDefault(a, SkillData.Builder.getDefault()).getShowInList())
					.sorted(Comparator.<String>comparingLong(a -> core.getData().getXpRaw(null, a)).reversed())
					.toList();
			var holderMap = lineRenderers;
			lineRenderers.clear();
			AtomicInteger yOffset = new AtomicInteger(0);
			skillGap = skillsKeys.stream()
					.map(skill -> fontRenderer.width(Component.translatable("pmmo."+skill).getString()))
					.max(Comparator.comparingInt(t -> t)).orElse(0);
			skillsKeys.forEach((skillKey)-> {
				var xpRaw = core.getData().getXpRaw(null, skillKey);
				lineRenderers.put(skillKey, 
					xpRaw != holderMap.getOrDefault(skillKey, SkillLine.DEFAULT).xpValue()
					? new SkillLine(skillKey, modifiers.getOrDefault(skillKey, 1.0), xpRaw, yOffset.get(), skillGap)
					: new SkillLine(holderMap.get(skillKey), yOffset.get()));
				yOffset.getAndIncrement();
			});
		}

		lineRenderers.forEach((skill, line) -> {
			line.render(graphics, renderX, renderY, fontRenderer);
		});
	}

private void renderVeinGauge(GuiGraphics graphics, double gaugeX, double gaugeY) {
		final int renderX = (int)((double)mc.getWindow().getGuiScaledWidth() * gaugeX);
		final int renderY = (int)((double)mc.getWindow().getGuiScaledHeight()* gaugeY);
		if (ClientTickHandler.isRefreshTick()) {
			maxCharge = VeinMiningLogic.getMaxChargeFromAllItems(mc.player);
			if (maxCharge > 0)
				currentCharge = VeinTracker.getCurrentCharge();
		}
		if (currentCharge > 0) {
			graphics.drawString(fontRenderer, LangProvider.VEIN_LIMIT.asComponent(Config.VEIN_LIMIT.get()), renderX, renderY-11, 0xFFFFFF);
			graphics.drawString(fontRenderer, LangProvider.VEIN_CHARGE.asComponent(currentCharge, maxCharge), renderX, renderY, 0xFFFFFF);
		}
	}

private void renderGains(GuiGraphics graphics, double listX, double listY) {
		final int renderX = (int)((double)mc.getWindow().getGuiScaledWidth() * listX);
		final int renderY = (int)((double)mc.getWindow().getGuiScaledHeight()* listY);
		for (int i = 0; i < ClientTickHandler.xpGains.size(); i++) {
			ClientTickHandler.GainEntry entry = ClientTickHandler.xpGains.get(i);
			graphics.drawString(fontRenderer, entry.display(), renderX, 3+renderY+ (i*9), entry.display().getStyle().getColor().getValue());
		}
	}

public SkillLine(String skillName, double bonus, long xpValue, int yOffset, int skillGap) {
			this(rawXpLine(xpValue, skillName), 
				Component.translatable("pmmo."+skillName), 
				bonusLine(bonus), 
				xpValue,
				CoreUtils.getSkillColor(skillName),
				yOffset * 9,
				skillGap);
		}

public SkillLine(SkillLine src, int yOffset) {
			this(src.xpRaw(), src.skillName(), src.bonusLine(), src.xpValue(), src.color, yOffset * 9, src.skillGap());
		}

private static String rawXpLine(long xpValue, String skillKey) {
			double level = ((DataMirror)Core.get(LogicalSide.CLIENT).getData()).getXpWithPercentToNextLevel(xpValue);
			int skillMaxLevel = SkillsConfig.SKILLS.get().getOrDefault(skillKey, SkillData.Builder.getDefault()).getMaxLevel();
			level = level > skillMaxLevel ? skillMaxLevel : level;
			return level >= Config.MAX_LEVEL.get() 
					? "" + Config.MAX_LEVEL.get() 
					: DP.dp(Math.floor(level * 100D) / 100D);
		}

private static String bonusLine(double bonus) {
			if (bonus != 1d) {
				bonus = (Math.max(0, bonus) -1) * 100d;
				return (bonus >= 0 ? "+" : "-")+DP.dp(bonus)+"%";
			}
			else return "";
		}

public void render(GuiGraphics graphics, int skillListX, int skillListY, Font fontRenderer) {
			int levelGap = fontRenderer.width(xpRaw());
			graphics.drawString(fontRenderer, xpRaw(), skillListX, skillListY + 3 + yOffset(), color());
			graphics.drawString(fontRenderer, " | " + skillName.getString(), skillListX + levelGap, skillListY + 3 + yOffset(), color());
			graphics.drawString(fontRenderer, " | " + DP.dprefix(xpValue()), skillListX + levelGap + skillGap() + 9, skillListY + 3 + yOffset(), color());
			graphics.drawString(fontRenderer, bonusLine, skillListX + levelGap + skillGap() + 46, skillListY + 3 + yOffset(), color());
		}

