@SuppressWarnings("unchecked")
	public void postProcess(RegistryAccess registryAccess) {
		Registry<V> activeRegistry = registryAccess.registryOrThrow(registry);
		MsLoggy.DEBUG.log(LOG_CODE.DATA, "Begin PostProcessing for {}", folderName);
		for (Map.Entry<ResourceLocation, T> dataRaw : new HashMap<>(this.data).entrySet()) {
			DataSource<T> dataValue = dataRaw.getValue();
			if (dataValue.getTagValues().isEmpty()) continue;
			MsLoggy.INFO.log(LOG_CODE.DATA, "Tag Data Found for {}", dataRaw.getKey().toString());
			List<ResourceLocation> tags = new ArrayList<>();
			for (String str : dataValue.getTagValues()) {
				MsLoggy.INFO.log(LOG_CODE.DATA, "Applying Setting to Tag: {}", str);
				if (str.startsWith("#")) {
                    activeRegistry
                            .getTag(TagKey.create(registry, new ResourceLocation(str.substring(1))))
							.ifPresent(tag -> tags.addAll(tag.stream()
									.map(holder -> holder.unwrapKey().get().location())
                                    .toList()));
                }
				else if (str.endsWith(":*")) {
					tags.addAll(activeRegistry.keySet()
							.stream()
							.filter(key -> key.getNamespace().equals(str.replace(":*", "")))
							.toList());
				}
				else
					tags.add(new ResourceLocation(str));
			}
			dataValue.getTagValues().clear();

			if (dataValue instanceof ObjectData entityData) {
				List<ResourceLocation> damageMembers = new ArrayList<>();
				for (EventType event : List.of(EventType.RECEIVE_DAMAGE, EventType.DEAL_DAMAGE)) {
					Map<String, Map<String, Long>> values = entityData.damageXpValues().getOrDefault(event, new HashMap<>());
					for (String str : values.keySet()) {
						damageMembers.clear();
						if (str.startsWith("#")) {
							damageMembers.addAll(registryAccess.registryOrThrow(Registries.DAMAGE_TYPE)
									.getTag(TagKey.create(Registries.DAMAGE_TYPE, new ResourceLocation(str.substring(1))))
									.stream()
									.map(type -> type.unwrapKey().get().location())
									.toList());

							damageMembers.forEach(damageType -> values
									.put(damageType.toString(), values.get(str)));
						}
					}


				}
			}

			tags.forEach(rl -> this.data.merge(rl, (T)dataValue, (o, n) -> o.combine(n)));
		}
		//Execute post-processing behavior (mostly logging at this point).
		finalizer.accept(this.data);
	}

public <PACKET> MergeableCodecDataManager<T, V> subscribeAsSyncable(final SimpleChannel channel,
		final Function<Map<ResourceLocation, T>, PACKET> packetFactory)
	{
		MinecraftForge.EVENT_BUS.addListener(this.getDatapackSyncListener(channel, packetFactory));
		return this;
	}

private <PACKET> Consumer<OnDatapackSyncEvent> getDatapackSyncListener(final SimpleChannel channel,
		final Function<Map<ResourceLocation, T>, PACKET> packetFactory)
	{
		return event -> {
			ServerPlayer player = event.getPlayer();
			List<PACKET> packets = new ArrayList<>();
			for (Map.Entry<ResourceLocation, T> entry : new HashMap<>(this.data).entrySet()) {
				if (entry.getKey() == null) continue;
				packets.add(packetFactory.apply(Map.of(entry.getKey(), entry.getValue())));
			}

			PacketTarget target = player == null
				? PacketDistributor.ALL.noArg()
				: PacketDistributor.PLAYER.with(() -> player);
			packets.forEach(packet -> channel.send(target, packet));
		};
	}

