@SuppressWarnings("resource")
	public static void handle(AnvilRepairEvent event) {
		Core core = Core.get(event.getEntity().level());
		CompoundTag eventHookOutput = new CompoundTag();
		boolean serverSide = !event.getEntity().level().isClientSide;
		EventType type = isEnchantBook(event.getLeft()) || isEnchantBook(event.getRight()) ? EventType.ENCHANT : EventType.ANVIL_REPAIR;
		if (serverSide)		
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(type, event, new CompoundTag());
		//Process perks
		CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(type, event.getEntity(), eventHookOutput));
		if (serverSide) {
			Map<String, Long> xpAward = core.getExperienceAwards(type, event.getOutput(), event.getEntity(), perkOutput);
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) event.getEntity());
			core.awardXP(partyMembersInRange, xpAward);	
		}
	}

private static boolean isEnchantBook(ItemStack stack) {
		return stack.getItem() instanceof EnchantedBookItem;
	}

@SuppressWarnings("resource")
	public static void handle(BreakEvent event) {
		Core core = Core.get(event.getPlayer().level());
		boolean serverSide = !event.getPlayer().level().isClientSide;
		if (!core.isActionPermitted(ReqType.BREAK, event.getPos(), event.getPlayer())) {
			event.setCanceled(true);
			Messenger.sendDenialMsg(ReqType.BREAK, event.getPlayer(), event.getState().getBlock().getName());
			return;
		}
		CompoundTag eventHookOutput = new CompoundTag();
		if (serverSide){
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.BLOCK_BREAK, event, new CompoundTag());
			if (eventHookOutput.getBoolean(APIUtils.IS_CANCELLED)) {
				event.setCanceled(true);
				return;
			}
		}
		//Process perks on both sides. note that only server-side perks will affect xp outputs.
		CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(EventType.BLOCK_BREAK, event.getPlayer(), eventHookOutput));
		if (serverSide) {
			Map<String, Long> xpAward = calculateXpAward(core, event, perkOutput);
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) event.getPlayer());
			core.awardXP(partyMembersInRange, xpAward);
			//update ChunkData to remove the block from the placed map
			//if a cascading breaking crop block, add the breaker value.
			LevelChunk chunk = (LevelChunk) event.getLevel().getChunk(event.getPos());
			chunk.getCapability(ChunkDataProvider.CHUNK_CAP).ifPresent(cap -> {
				cap.delPos(event.getPos());
				if (event.getLevel().getBlockState(event.getPos()).is(Reference.CASCADING_BREAKABLES))
					cap.setBreaker(event.getPos(), event.getPlayer().getUUID());
			});;
			chunk.setUnsaved(true);
		}
		//==============Process Vein Miner Logic==================
		if (core.getMarkedPos(event.getPlayer().getUUID()).equals(event.getPos())) {
			BlockState block = event.getLevel().getBlockState(event.getPos());
			Item tool = event.getPlayer().getMainHandItem().getItem();
			if (!Config.VEIN_BLACKLIST.get().contains(RegistryUtil.getId(tool).toString())) {
				VeinMiningLogic.applyVein((ServerPlayer) event.getPlayer(), event.getPos());
			}
		}
	}

private static Map<String, Long> calculateXpAward(Core core, BreakEvent event, CompoundTag dataIn) {
		Map<String, Long> outMap = core.getExperienceAwards(EventType.BLOCK_BREAK, event.getPos(), (Level)event.getLevel(), event.getPlayer(), dataIn); 
		LevelChunk chunk = (LevelChunk) event.getLevel().getChunk(event.getPos());
		IChunkData cap = chunk.getCapability(ChunkDataProvider.CHUNK_CAP).orElseGet(ChunkDataHandler::new);
		if (cap.playerMatchesPos(event.getPlayer(), event.getPos())) {
			//Do not apply self-place penalty to crops
			BlockState cropState = event.getLevel().getBlockState(event.getPos()); 
			if (cropState.getBlock() instanceof CropBlock && ((CropBlock)cropState.getBlock()).isMaxAge(cropState))
				return outMap;
			double xpModifier = Config.REUSE_PENALTY.get();
			if (xpModifier == 0) return new HashMap<>();
			Map<String, Long> modifiedOutMap = new HashMap<>();
			outMap.forEach((k, v) -> modifiedOutMap.put(k, (long)((double)v * xpModifier)));
			return modifiedOutMap;
		}
		return outMap;
	}

public DetailsCache(ItemStack item, BlockPos pos, BlockState state, boolean cancelled, float newSpeed) {
			this(item, pos, state, true, cancelled, newSpeed);
		}

@SuppressWarnings("resource")
	public static void handle(BreakSpeed event) {
		Core core = Core.get(event.getEntity().level());
		//First, check the cache for a repeat event trigger
		if (resultCache.containsKey(event.getEntity().getUUID())) {
			if (usingCache(event)) {
				MsLoggy.DEBUG.log(LOG_CODE.EVENT, "Cache Used. Supplied: {}", event.getNewSpeed());
				return;
			}
		}
		//calculate the event results anew.
		if (!core.isActionPermitted(ReqType.TOOL, event.getEntity().getMainHandItem(), event.getEntity())) {
			event.setCanceled(true);
			//Cache the result for future event occurrences
			resultCache.put(event.getEntity().getUUID(), 
					new DetailsCache(event.getEntity().getMainHandItem(), event.getPosition().orElse(new BlockPos(0,0,0)), event.getState(), true, event.getNewSpeed()));
			return;
		}
		if (!core.isActionPermitted(ReqType.BREAK, event.getPosition().orElse(new BlockPos(0,0,0)), event.getEntity())) {
			event.setCanceled(true);
			resultCache.put(event.getEntity().getUUID(), 
					new DetailsCache(event.getEntity().getMainHandItem(), event.getPosition().orElse(new BlockPos(0,0,0)), event.getState(), true, event.getNewSpeed()));
			return;
		}
		CompoundTag eventHookOutput = new CompoundTag();
		if (!event.getEntity().level().isClientSide){
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.BREAK_SPEED, event, new CompoundTag());
			if (eventHookOutput.getBoolean(APIUtils.IS_CANCELLED)) {
				event.setCanceled(true);
				resultCache.put(event.getEntity().getUUID(), 
						new DetailsCache(event.getEntity().getMainHandItem(), event.getPosition().orElse(new BlockPos(0,0,0)), event.getState(), true, event.getNewSpeed()));
				return;
			}
		}
		CompoundTag perkDataIn = eventHookOutput;
		perkDataIn.putFloat(APIUtils.BREAK_SPEED_INPUT_VALUE, event.getNewSpeed());
		perkDataIn.putLong(APIUtils.BLOCK_POS, event.getPosition().orElse(new BlockPos(0,0,0)).asLong());

		CompoundTag perkDataOut = core.getPerkRegistry().executePerk(EventType.BREAK_SPEED, event.getEntity(), perkDataIn);
		if (perkDataOut.contains(APIUtils.BREAK_SPEED_OUTPUT_VALUE)) {
			float newSpeed = event.getNewSpeed() * (1 + Math.max(0, perkDataOut.getFloat(APIUtils.BREAK_SPEED_OUTPUT_VALUE)));
			MsLoggy.INFO.log(LOG_CODE.EVENT, "BreakSpeed Original{}, New:{}",event.getOriginalSpeed(), newSpeed);
			event.setNewSpeed(newSpeed);
			resultCache.put(event.getEntity().getUUID(), 
					new DetailsCache(event.getEntity().getMainHandItem(), event.getPosition().orElse(new BlockPos(0,0,0)), event.getState(), event.getEntity().onGround(), false, newSpeed));
		}			
	}

private static boolean usingCache(BreakSpeed event) {
		DetailsCache cachedData = resultCache.get(event.getEntity().getUUID());
		if (event.getEntity().onGround() == cachedData.isPlayerStanding()
			&&event.getPosition().orElse(new BlockPos(0,0,0)).equals(cachedData.pos)
			&& event.getState().equals(cachedData.state)
			&& event.getEntity().getMainHandItem().equals(cachedData.item, false)) {			
			if (cachedData.cancelled) 
				event.setCanceled(true);
			else 
				event.setNewSpeed(cachedData.newSpeed);
			return true;
		}
		return false;
	}

