@SuppressWarnings("resource")
	public static void handle(FurnaceBurnEvent event) {
		//Checkers to exit early for non-applicable conditions
		if (event.getLevel().isClientSide) return;
		IChunkData cap = event.getLevel().getChunkAt(event.getPos()).getCapability(ChunkDataProvider.CHUNK_CAP).orElseGet(ChunkDataHandler::new);
		UUID pid = cap.checkPos(event.getPos());
		if (pid == null) return;
		ServerPlayer player = event.getLevel().getServer().getPlayerList().getPlayer(pid);
		if (player == null) {
			Optional<GameProfile> playerProfile = event.getLevel().getServer().getProfileCache().get(pid);
			if (playerProfile.isEmpty()) 
				return;
			player = new ServerPlayer(event.getLevel().getServer(), (ServerLevel) event.getLevel(), playerProfile.get());
		}

		//core logic 
		Core core = Core.get(event.getLevel());
		CompoundTag eventHook = core.getEventTriggerRegistry().executeEventListeners(EventType.SMELT, event, new CompoundTag());
		eventHook.putString(APIUtils.STACK, event.getInput().serializeNBT().getAsString());
		eventHook = TagUtils.mergeTags(eventHook, core.getPerkRegistry().executePerk(EventType.SMELT, player, eventHook));
		Map<String, Long> xpAwards = core.getExperienceAwards(EventType.SMELT, event.getInput(), player, eventHook);
		core.getExperienceAwards(EventType.SMELTED, event.getOutput(), player, eventHook).forEach((skill, award) -> xpAwards.merge(skill, award, Long::sum));
		List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange(player);
		core.awardXP(partyMembersInRange, xpAwards);

	}

@SuppressWarnings("resource")
	public static void handle(LivingJumpEvent event) {
		if (!(event.getEntity() instanceof Player)) return;
		Player player = (Player) event.getEntity();

		EventType type = EventType.JUMP;
		if (player.isSprinting()) type = EventType.SPRINT_JUMP;
		else if (player.isCrouching()) type = EventType.CROUCH_JUMP;

		Core core = Core.get(player.level());
		CompoundTag eventHookOutput = new CompoundTag();
		boolean serverSide = !player.level().isClientSide; 
		if (serverSide){			
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(type, event, new CompoundTag());
			if (eventHookOutput.getBoolean(APIUtils.IS_CANCELLED)) {
				event.setCanceled(true);
				return;
			}
		}
		//Process perks
		CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(type, player, eventHookOutput));
		if (serverSide) {
			//NOTE a default value of 0.4 is consistent with the base jump amount of a player without any vanilla/modded jump modifiers
			double jumpXpBase = perkOutput.contains(APIUtils.JUMP_OUT) ? Math.max(0.4, perkOutput.getDouble(APIUtils.JUMP_OUT)) : player.getDeltaMovement().y;
			Map<String, Long> xpAward = new HashMap<>();
			Map<String, Double> ratios = getRatioMap(type);
			ratios.keySet().forEach((skill) -> {
				Double xpValue = ratios.getOrDefault(skill, 2.5) * jumpXpBase * core.getConsolidatedModifierMap(player).getOrDefault(skill, 1d);
				xpAward.put(skill, xpValue.longValue());
			});
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) player);
			core.awardXP(partyMembersInRange, xpAward);	
		}
	}

private static Map<String, Double> getRatioMap(EventType type) {
		return type.equals(EventType.JUMP) ? Config.JUMP_XP.get() 
				: type.equals(EventType.SPRINT_JUMP) ? Config.SPRINT_JUMP_XP.get() 
						: type.equals(EventType.CROUCH_JUMP) ? Config.CROUCH_JUMP_XP.get() : new HashMap<>();  
	}

