@SuppressWarnings("resource")
	public static void handle(AnimalTameEvent event) {
		Core core = Core.get(event.getTamer().level());
		Player player = event.getTamer();
		Animal target = event.getAnimal();

		if (!core.isActionPermitted(ReqType.TAME, target, player)) {
			event.setCanceled(true);
			Messenger.sendDenialMsg(ReqType.TAME, player, target.getName());
			return;
		}
		boolean serverSide = !player.level().isClientSide;
		CompoundTag hookOutput = new CompoundTag();
		if (serverSide) {
			hookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.TAMING, event, new CompoundTag());
			if (hookOutput.getBoolean(APIUtils.IS_CANCELLED)) {
				event.setCanceled(true);
				return;
			}
		}
		//Process perks
		hookOutput.putUUID(PerksImpl.ANIMAL_ID, event.getAnimal().getUUID());
		hookOutput = TagUtils.mergeTags(hookOutput, core.getPerkRegistry().executePerk(EventType.TAMING, player, hookOutput));
		if (serverSide) {
			Map<String, Long> xpAward = core.getExperienceAwards(EventType.TAMING, target, player, hookOutput);
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) player);
			core.awardXP(partyMembersInRange, xpAward);
		}
	}

public static void handle(TradeWithVillagerEvent event) {
        ItemStack tradeA = event.getMerchantOffer().getCostA();
        ItemStack tradeB = event.getMerchantOffer().getCostB();
        ItemStack result = event.getMerchantOffer().getResult();
        Core core = Core.get(event.getEntity().level());

        CompoundTag eventHookOutput = new CompoundTag();
        boolean serverSide = !event.getEntity().level().isClientSide;
        if (serverSide) {
            eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.GIVEN_AS_TRADE, event, new CompoundTag());
            eventHookOutput = TagUtils.mergeTags(eventHookOutput, core.getEventTriggerRegistry().executeEventListeners(EventType.RECEIVED_AS_TRADE, event, new CompoundTag()));
        }
        //Process perks
        CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(EventType.GIVEN_AS_TRADE, event.getEntity(), eventHookOutput));
        perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(EventType.RECEIVED_AS_TRADE, event.getEntity(), perkOutput));
        if (serverSide) {
            Map<String, Long> xpAward = core.getExperienceAwards(EventType.GIVEN_AS_TRADE, tradeA, event.getEntity(), perkOutput)
                    .entrySet().stream().map(entry -> {entry.setValue(entry.getValue() * tradeA.getCount()); return entry;})
                    .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
            core.getExperienceAwards(EventType.GIVEN_AS_TRADE, tradeB, event.getEntity(), perkOutput)
                    .forEach((skill, value) -> xpAward.merge(skill, value * tradeB.getCount(), Long::sum));
            core.getExperienceAwards(EventType.RECEIVED_AS_TRADE, result, event.getEntity(), perkOutput)
                    .forEach((skill, value) -> xpAward.merge(skill, value * result.getCount(), Long::sum));
            List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) event.getEntity());
            core.awardXP(partyMembersInRange, xpAward);
        }
    }

private static void setupServer(ForgeConfigSpec.Builder builder) {
		builder.comment("Anti-Cheese is a system for managing how XP is gained.",
				"There are various ways in which players can exploit",
				"features of various mods and mechanics to gain xp at",
				"rates that are not intended.  The below anti-cheese",
				"features address many of the most common.")
			.push("AntiCheese");

		AFK_CAN_SUBTRACT = builder.comment("if set to true, players who are AFK will continuously grow their",
				"reduction value and will end up gaining negative xp.",
				"If this is false, they only stop gaining and never lose.")
				.define("AFK_Can_Subtract", false);

		SETTINGS_AFK = TomlConfigHelper.defineObject(builder.comment("AFK Tracking allows you to control if and when a player",
				"should not gain xp while afk.  All afk timers are configuration",
				"specific, so you can configure separate thresholds for different",
				"types of xp."
				), "AFK", CODEC, Map.of(EventType.SUBMERGED, Setting.build().minTime(200).reduction(0.1).cooloff(1).build(),
								EventType.SWIMMING, Setting.build().minTime(200).reduction(0.1).cooloff(1).build(),
								EventType.DIVING, Setting.build().minTime(200).reduction(0.1).cooloff(1).build(),
								EventType.SURFACING, Setting.build().minTime(200).reduction(0.1).cooloff(1).build(),
								EventType.SWIM_SPRINTING, Setting.build().minTime(200).reduction(0.1).cooloff(1).build()));

		SETTINGS_DIMINISHING = TomlConfigHelper.defineObject(builder.comment("Diminishing XP allows you to reduce the amount of XP earned",
				"for a specific event when the xp is earned in quick succession."
				), "DiminishingXP", CODEC, Map.of(EventType.RIDING, Setting.build()
						.source("minecraft:horse","minecraft:boat").retention(200).reduction(0.005).build()));		

		SETTINGS_NORMALIZED = TomlConfigHelper.defineObject(builder.comment("Normalization allows you to keep xp gain values from spiking",
				"by keeping them within a range of tolerance.  When normalized,",
				"xp from an event will not exceed the threshold above the previously",
				"earned xp value."
				), "Normalization", CODEC, Map.of(EventType.SPRINTING, Setting.build().retention(400).tolerance(0.1).tolerance(10).build()));

		builder.pop();

	}

public static void applyAntiCheese(EventType event, ResourceLocation source, Player player, Map<String, Long> awardIn) {
		if (player == null || event == null || !(player instanceof ServerPlayer))
			return;
		Setting setting = AntiCheeseConfig.SETTINGS_AFK.get().get(event); 
		if (setting != null)
			setting.applyAFK(event, source, player, awardIn);
		if ((setting = AntiCheeseConfig.SETTINGS_DIMINISHING.get().get(event)) != null)
			setting.applyDiminuation(event, source, player, awardIn);
		if ((setting = AntiCheeseConfig.SETTINGS_NORMALIZED.get().get(event)) != null)
			setting.applyNormalization(event, source, player, awardIn);
	}

@SubscribeEvent
	public static void playerWatcher(ServerTickEvent event) {
		if (event.phase == TickEvent.Phase.END || event.side == LogicalSide.CLIENT) 
			return;

		AFK_DATA.forEach((player, map) -> map.forEach((type, tracker) -> {
			if (player != null && !tracker.meetsAFKCriteria(player))
				tracker.cooldown();
		}));
		DIMINISH_DATA.forEach((player, map) -> map.forEach((type, tracker) -> tracker.cooloff()));
		NORMALIZED_DATA.forEach((player, map) -> map.forEach((type, tracker) -> tracker.retainTimeRemaining--));
	}

public AFKTracker(Player player, int minDuration, int cooldownBy, int tolerance, boolean strictFacing) {
			this.lastPos = player.blockPosition();
			this.lastLookAngle = player.getLookAngle();
			this.minDuration = minDuration;
			this.cooldownBy = cooldownBy;
			this.tolerance = tolerance;
			this.strictFacing = strictFacing;
		}

public AFKTracker update(Player player) {
			if (meetsAFKCriteria(player))
				durationAFK++;
			else if (durationAFK <= 0){
				lastLookAngle = player.getLookAngle();
				lastPos = player.blockPosition();
			}
			return this;
		}

public void cooldown() {
			if (durationAFK > 0)
				durationAFK -= cooldownBy;
		}

public boolean meetsAFKCriteria(Player player) {
			BlockPos curPos = player.blockPosition();
			return (!strictFacing || lastLookAngle.equals(player.getLookAngle()))
					&& Math.abs(lastPos.getX() - curPos.getX()) < tolerance
					&& Math.abs(lastPos.getY() - curPos.getY()) < tolerance
					&& Math.abs(lastPos.getZ() - curPos.getZ()) < tolerance;
		}

public boolean isAFK() {
			return MsLoggy.DEBUG.logAndReturn(durationAFK >= minDuration, LOG_CODE.FEATURE, "isAFK:{}({}:{})", durationAFK, minDuration);
		}

public int getAFKDuration() {
			return durationAFK - minDuration;
		}

public NormTracker(int defaultRetention) {
			this.retainTimeRemaining = defaultRetention;
		}

public DiminishTracker(int timeToClear) {
			this.timeToClearReduction = timeToClear;
		}

public void cooloff() {
			if (--cooloffLeft <= 0)
				persistedTime = 0;
		}

public void diminish() {
			persistedTime++;
			cooloffLeft = timeToClearReduction;
		}

public Builder source(String entry) {
				source.add(entry);
				return this;
			}

public Builder source(String...entries) {
				source.addAll(Arrays.asList(entries));
				return this;
			}

public Builder minTime(int min) {
				this.minTime = min;
				return this;
			}

public Builder retention(int ret) {
				this.retention = ret;
				return this;
			}

public Builder reduction(double red) {
				this.reduction = red;
				return this;
			}

public Builder cooloff(int cool) {
				this.cooloff = cool;
				return this;
			}

public Builder tolerance(int flat) {
				this.toleranceFlat = flat;
				return this;
			}

public Builder tolerance(double percent) {
				this.tolerancePercent = percent;
				return this;
			}

public Builder setStrictness(boolean isStrict) {
				this.strictTolerance = isStrict;
				return this;
			}

public Setting build() {
				return new Setting(source, minTime, retention, toleranceFlat, reduction, cooloff, tolerancePercent, strictTolerance);
			}

public void applyAFK(EventType event, ResourceLocation source, Player player, Map<String, Long> awardIn) {
			AFKTracker afkData = AFK_DATA.computeIfAbsent(player, p -> new HashMap<>())
					.computeIfAbsent(event, e -> new AFKTracker(player, minTime(), cooloff(), toleranceFlat(), strictTolerance())).update(player);
			if ((this.source().isEmpty() || this.source().contains(source.toString())) && afkData.isAFK()) {
				awardIn.keySet().forEach(skill -> {
					MsLoggy.DEBUG.log(LOG_CODE.XP, "AFK reduction factor: {}", reduction * (double)afkData.getAFKDuration());
					awardIn.compute(skill, (key, xp) -> {
						long reductionAmount = Double.valueOf(xp * (reduction * (double)afkData.getAFKDuration())).longValue();						
						return xp - (AntiCheeseConfig.AFK_CAN_SUBTRACT.get()
									? reductionAmount
									: reductionAmount > xp ? xp : reductionAmount);
					});
				});
			}
		}

public void applyDiminuation(EventType event, ResourceLocation source, Player player, Map<String, Long> awardIn) {
			var tracker = DIMINISH_DATA.computeIfAbsent(player, p -> new HashMap<>()).computeIfAbsent(event, e -> new DiminishTracker(retention));
			if (this.source().isEmpty() || this.source().contains(source.toString())) {				
				tracker.diminish();
				awardIn.keySet().forEach(skill -> {
					double reductionScale = 1d - (reduction * (double)tracker.persistedTime);
					awardIn.compute(skill, (key, xp) -> Double.valueOf((double)xp * Math.max(0d, reductionScale)).longValue());
				});
			}
		}

public void applyNormalization(EventType event, ResourceLocation source, Player player, Map<String, Long> awardIn) {			
			if (this.source().isEmpty() || this.source().contains(source.toString())) {
				NormTracker norms = NORMALIZED_DATA.computeIfAbsent(player, p -> new HashMap<>()).computeIfAbsent(event, e -> new NormTracker(retention));
				norms.retainTimeRemaining = retention;
				awardIn.forEach((skill, value) -> {
					long norm = norms.norms.computeIfAbsent(skill, s -> value);
					long acceptableVariance = Double.valueOf(Math.min(norm + (Math.max(1d, (double)norm * tolerancePercent)), norm + toleranceFlat)).longValue();
					norms.norms.put(skill, value > acceptableVariance ? acceptableVariance : value);
				});
				awardIn.putAll(norms.norms);
			}
		}

public static Map<String, Integer> processReqs(ReqType type, ResourceLocation blockID) {

		//exit early if the type is not valid for a block
		if (!type.blockApplicable || isWorldSensitive(blockID) || !AutoValueConfig.isReqEnabled(type))
			return new HashMap<>();

		Block block = ForgeRegistries.BLOCKS.getValue(blockID);
		Map<String, Integer> outMap = new HashMap<>();
		switch (type) {
		case BREAK -> {
			//this water check exists solely to capture breaking waterlogged blocks
			//while autovalues are on, which spams chat with notification the user
			//is unable to break water blocks.
			if (block.equals(Blocks.WATER)) break;

			float breakSpeed = block.defaultBlockState().getDestroySpeed(EmptyBlockGetter.INSTANCE, null);
			AutoValueConfig.getBlockReq(type).forEach((skill, level) -> {
				outMap.put(skill, (int)Math.max(0, (breakSpeed - BASE_HARDNESS) * AutoValueConfig.HARDNESS_MODIFIER.get()));
			});
		}
		default -> {}}
		return outMap;
	}

public static Map<String, Long> processXpGains(EventType type, ResourceLocation blockID) {
		//exit early if the type is not valid for a block
		if (!type.blockApplicable || isWorldSensitive(blockID) || !AutoValueConfig.isXpGainEnabled(type))
			return new HashMap<>();

		Block block = ForgeRegistries.BLOCKS.getValue(blockID);
		Map<String, Long> outMap = new HashMap<>();
		switch (type) {
		case BLOCK_BREAK: case BLOCK_PLACE: {
			if (ForgeRegistries.BLOCKS.tags().getTag(Reference.CROPS).contains(block))
				outMap.putAll(AutoValueConfig.getBlockXpAward(EventType.GROW));
			else if (ForgeRegistries.BLOCKS.tags().getTag(Reference.MINABLE_AXE).contains(block))
				outMap.putAll(AutoValueConfig.AXE_OVERRIDE.get());
			else if (ForgeRegistries.BLOCKS.tags().getTag(Reference.MINABLE_HOE).contains(block))
				outMap.putAll(AutoValueConfig.HOE_OVERRIDE.get());
			else if (ForgeRegistries.BLOCKS.tags().getTag(Reference.MINABLE_SHOVEL).contains(block))
				outMap.putAll(AutoValueConfig.SHOVEL_OVERRIDE.get());
			else
				AutoValueConfig.getBlockXpAward(type).forEach((skill, level) -> {
					float breakSpeed = Math.max(1, block.defaultBlockState().getDestroySpeed(null, null));
					long xpOut = Double.valueOf(Math.max(1, breakSpeed * AutoValueConfig.HARDNESS_MODIFIER.get() * level)).longValue();
					if (ForgeRegistries.BLOCKS.tags().getTag(Tags.Blocks.ORES).contains(block))
						xpOut *= AutoValueConfig.RARITIES_MODIFIER.get();
					outMap.put(skill, xpOut);
				});
			break;
		}
		case GROW: {
			if (block instanceof CropBlock) {
				outMap.putAll(AutoValueConfig.getBlockXpAward(type));
			}
			break;
		}
		default: }
		return outMap;	
	}

